laboratory.referenceCode:
#include <iostream>
struct Item { int id{}; int stock{}; };
bool issue(Item& item, int amount) {
    if (item.id < 1 || item.id > 1000 || item.stock < 0 || item.stock > 1000 || amount < 0 || amount > item.stock) { return false; }
    item.stock -= amount;
    return true;
}
int main() {
    Item value;
    int amount{};
    if (!(std::cin >> value.id >> value.stock >> amount)) { std::cout << "invalid\n"; return 0; }
    std::cin >> std::ws;
    if (!std::cin.eof() || value.id < 1 || value.id > 1000 || value.stock < 0 || value.stock > 1000 || amount < 0 || amount > 1000) { std::cout << "invalid\n"; return 0; }
    bool ok = issue(value, amount);
    std::cout << (ok ? "ok " : "rejected ") << value.stock << '\n';
}
